// Tiered PowerShell validation: one command, fail-fast, compact summary.
//
//   node ai-docs/tools/validate.mjs quick --label NAME [--fork WORKTREE] [--keep-scratch]
//   node ai-docs/tools/validate.mjs full  --label NAME [--only a,b] [--skip a,b] [--dune-jobs N] [--keep-scratch]
//   node ai-docs/tools/validate.mjs promote LABEL [--allow-dirty]
//
// Paths come from config.mjs (optional ai-docs/local/config.json). Every parser gate
// uses the parser Opengrep runs: the simplified ABI 14 parser (opengrep/ocaml/lib,
// generated by tree-sitter 0.22.6) on the 0.22.6 runtime.
//   source:  eslint on grammar.js; inherited upstream test cases intact.
//   compat:  0.22 corpus tests; ABI14 parser; committed test/*.c on it.
//   grammar: grammar harness with ts-dump on the ABI14 parser, reporting the
//            unsimplified grammar's node names (grammar-harness/abi14-names.mjs).
// quick: fix-worktree checks with no Dune and no shared generator output, so
//        several fix agents may run it at once. Stages: source, compat, grammar.
//        --fork defaults to this grammar repo. compat builds the ABI14 parser into the
//        run folder (abi14-build.mjs, shared with proof-kit.mjs) and raw-parses the
//        corpus with it; grammar uses that parser.
// full:  certification of the integrated checkout (Opengrep superproject + this repo;
//        holds an exclusive lock). Stages: source, compat, grammar, build, unit, corpus,
//        smoke. compat regenerates opengrep/ocaml; grammar uses that parser; smoke scans
//        every readable PowerShell file of each batch with the rules in smoke/rules.yaml.
// promote: make a complete passing full run the "current" baseline (local/baselines.json).
//
// Corpus: every subfolder of the corpus root is a batch. Without one, the grammar,
// corpus and smoke stages are skipped with a notice and the run is not a certification.
// Without a baseline (or a batch the baseline lacks), comparisons report "no baseline".
// Output: local/runs/LABEL/ (summary.{json,txt}, logs/, grammar|corpus|smoke/BATCH/).
// Exit 0 = pass, 1 = fail.
import assert from 'node:assert/strict';
import { spawn, spawnSync, execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { once } from 'node:events';
import { fileURLToPath } from 'node:url';
import {
  AI_DOCS, TOOLS, PARSER, ROOT, CORPUS, RT22, ABI14_LIB, GENERATOR, LOCK, RUNS, BASELINES, NATIVE_CACHE, PROBE,
  batches, prepareLocal, requireRoot, requireVendor,
} from './config.mjs';
import { ABI14_CC, ABI14_RUNTIME, q, StageFailure, sh, buildAbi14, abi14NamesMap, tsDumpCommand, opengrepDir } from './abi14-build.mjs';

const SELF = fileURLToPath(import.meta.url);
const SMOKE_RULES = path.join(TOOLS, 'smoke/rules.yaml');
const OCAML_LINT = ['Parse_powershell_tree_sitter.ml', 'Unit_powershell.ml']
  .map(name => `languages/powershell/generic/${name}`);
const CLK_TCK = Number(execFileSync('getconf', ['CLK_TCK'], { encoding: 'utf8' }).trim());
const STAGES = { quick: ['source', 'compat', 'grammar'], full: ['source', 'compat', 'grammar', 'build', 'unit', 'corpus', 'smoke'] };
const CORPUS_STAGES = ['grammar', 'corpus', 'smoke'];
const SCRATCH = ['c-tests', 'ts-dump', 'names-022', 'compat-repo', 'compat-022', 'compat-abi14', 'compat-lib',
  'ocaml-tree-sitter-gen.exe', 'corpus-probe', 'inputs'];

const readJson = file => JSON.parse(fs.readFileSync(file, 'utf8'));
const readJsonl = file => fs.readFileSync(file, 'utf8').trim().split('\n').map(JSON.parse);
const rel = file => path.relative(AI_DOCS, file);
const sha256 = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const sameFile = (a, b) => fs.existsSync(a) && fs.existsSync(b) && fs.readFileSync(a).equals(fs.readFileSync(b));
const git = (dir, ...args) => execFileSync('git', ['-C', dir, ...args], { encoding: 'utf8', maxBuffer: 256e6 }).trim();
const duration = s => s < 60 ? `${s.toFixed(1)}s` : `${Math.floor(s / 60)}m${String(Math.round(s % 60)).padStart(2, '0')}s`;
const loadBaselines = () => fs.existsSync(BASELINES) ? readJson(BASELINES) : { current: null, history: [] };

function childCpuSeconds() {
  // Linux: cutime + cstime include every reaped descendant, so per-stage deltas
  // separate CPU-bound work from waiting even though stages spawn many processes.
  const stat = fs.readFileSync('/proc/self/stat', 'utf8');
  const fields = stat.slice(stat.lastIndexOf(')') + 2).split(' ');
  return (Number(fields[13]) + Number(fields[14])) / CLK_TCK;
}

function parseArgs(argv) {
  const [tier, ...rest] = argv;
  const opts = { tier, positional: [] };
  for (let i = 0; i < rest.length; i++) {
    const arg = rest[i];
    if (arg === '--allow-dirty' || arg === '--keep-scratch') opts[arg === '--allow-dirty' ? 'allowDirty' : 'keepScratch'] = true;
    else if (arg.startsWith('--')) {
      assert.ok(i + 1 < rest.length, `${arg} needs a value`);
      opts[arg.slice(2).replace(/-(\w)/g, (_, c) => c.toUpperCase())] = rest[++i];
    } else opts.positional.push(arg);
  }
  return opts;
}

function gitIdentity(dir) {
  const status = git(dir, 'status', '--porcelain');
  return {
    path: dir, head: git(dir, 'rev-parse', 'HEAD'), short: git(dir, 'rev-parse', '--short=9', 'HEAD'),
    branch: git(dir, 'branch', '--show-current'), dirty: status !== '', status: status ? status.split('\n') : [],
  };
}

class Run {
  constructor(opts) {
    this.opts = opts;
    this.tier = opts.tier;
    this.label = opts.label;
    assert.match(this.label ?? '', /^[A-Za-z0-9][A-Za-z0-9._-]*$/, '--label NAME is required (letters, digits, . _ -)');
    for (const key of Object.keys(opts)) {
      assert.ok(['tier', 'positional', 'label', 'fork', 'only', 'skip', 'duneJobs', 'keepScratch'].includes(key), `unknown option for ${this.tier}: ${key}`);
    }
    assert.ok(this.tier === 'quick' || !opts.fork, '--fork goes with quick; full validates this grammar repo');
    requireRoot();
    requireVendor(RT22);
    prepareLocal();
    this.baseline = loadBaselines().current;
    this.fork = path.resolve(this.tier === 'quick' ? opts.fork ?? PARSER : PARSER);
    assert.ok(fs.existsSync(path.join(this.fork, 'grammar.js')), `not a parser worktree: ${this.fork}`);
    const all = STAGES[this.tier];
    const only = opts.only?.split(',');
    const skip = opts.skip?.split(',') ?? [];
    for (const name of [...(only ?? []), ...skip]) assert.ok(all.includes(name), `unknown ${this.tier} stage: ${name}`);
    this.selected = all.filter(name => (!only || only.includes(name)) && !skip.includes(name));
    this.batches = batches();
    if (!this.batches.length) {
      this.noCorpus = `no corpus batches in ${CORPUS}`;
      this.selected = this.selected.filter(name => !CORPUS_STAGES.includes(name));
    }
    this.complete = STAGES[this.tier].every(name => this.selected.includes(name));
    assert.ok(this.tier !== 'quick' || !this.selected.includes('grammar') || this.selected.includes('compat'),
      'the quick grammar stage needs the compat stage, which builds the ABI14 parser');
    assert.ok(!this.selected.includes('smoke') || this.selected.includes('corpus'),
      'the smoke stage needs the corpus stage, whose inventory gives its targets and error classes');
    this.dir = path.join(RUNS, this.label);
    assert.ok(!fs.existsSync(this.dir), `${rel(this.dir)} already exists; choose a new --label`);
    fs.mkdirSync(path.join(this.dir, 'logs'), { recursive: true });
    this.stages = [];
    this.counts = {};
  }

  output(family, batch) {
    return path.join(this.dir, family, batch);
  }

  // The baseline's result folder for FAMILY and BATCH, or null (no baseline for it).
  base(family, batch) {
    if (!this.baseline?.batches.includes(batch)) return null;
    const dir = path.join(RUNS, this.baseline.label, family, batch);
    assert.ok(fs.existsSync(dir), `baseline ${this.baseline.label} lacks ${rel(dir)}`);
    return dir;
  }

  async stage(name, fn) {
    const log = path.join(this.dir, 'logs', `${name}.log`);
    const fd = fs.openSync(log, 'a');
    const record = { name, status: 'running', started_at: new Date().toISOString(), loadavg_1m: os.loadavg()[0], log: rel(log) };
    this.stages.push(record);
    process.stdout.write(`[${name}] running... `);
    const cpu = childCpuSeconds();
    const start = performance.now();
    try {
      record.details = await fn({ fd, sh: (script, options) => sh(fd, script, options) });
      record.status = 'pass';
    } catch (error) {
      record.status = 'fail';
      record.error = error instanceof StageFailure || error instanceof assert.AssertionError
        ? error.message : String(error.stack ?? error);
      fs.writeSync(fd, `\nVALIDATION FAILURE: ${record.error}\n`);
    } finally {
      record.wall_s = +((performance.now() - start) / 1000).toFixed(3);
      record.child_cpu_s = +(childCpuSeconds() - cpu).toFixed(2);
      fs.closeSync(fd);
    }
    console.log(`${record.status.toUpperCase()} ${duration(record.wall_s)}`);
    return record.status === 'pass';
  }

  checkCount(key, value) {
    this.counts[key] = value;
    const expected = this.tier === 'full' ? this.baseline?.counts?.[key] : undefined;
    assert.ok(expected === undefined || value >= expected, `${key} dropped from ${expected} to ${value}`);
  }
}

// ---------------------------------------------------------------- stages

async function sourceStage(run, { sh }) {
  const fork = run.fork;
  assert.ok(fs.existsSync(path.join(PARSER, 'node_modules/.bin/eslint')),
    `no ${PARSER}/node_modules/.bin/eslint; run: npm ci --ignore-scripts (see ai-docs/README.md)`);
  assert.ok(spawnSync('git', ['-C', fork, 'rev-parse', '--verify', '--quiet', 'upstream/main^{commit}']).status === 0,
    'no upstream/main; add and fetch Airbus\'s repository as the upstream remote (see ai-docs/README.md)');
  const lint = await sh(`${q(PARSER)}/node_modules/.bin/eslint --config ${q(PARSER)}/eslint.config.mjs grammar.js`,
    { cwd: fork, capture: true });
  assert.ok(!/ignored/i.test(lint.stdout), 'eslint ignored grammar.js');

  const inherited = git(fork, 'ls-tree', '-r', '-z', '--name-only', 'upstream/main', 'test').split('\0').filter(Boolean);
  let inheritedCases = 0;
  const changed = inherited.flatMap(file => {
    const original = execFileSync('git', ['-C', fork, 'show', `upstream/main:${file}`], { maxBuffer: 256e6 }).toString('utf8');
    const current = path.join(fork, file);
    if (!fs.existsSync(current)) return [`${file} (deleted)`];
    const text = fs.readFileSync(current, 'utf8');
    if (!file.startsWith('test/corpus/')) return text === original ? [] : [file];
    // New cases may be appended; every original case must remain verbatim.
    const cases = corpusCases(original);
    inheritedCases += cases.length;
    return cases.filter(block => !containsCase(text, block)).map(block => `${file}: ${block.split('\n')[1]}`);
  });
  assert.deepEqual(changed, [], 'inherited upstream test cases changed');
  return {
    eslint: 'ok', inherited_test_cases_unchanged: inheritedCases,
    line: `eslint ok; ${inheritedCases} inherited cases intact`,
  };
}

function corpusCases(text) {
  // A case starts at a header delimiter that is followed by a name and a second delimiter.
  const lines = text.split('\n');
  const isDelimiter = line => /^={3,}\S*$/.test(line);
  const starts = [];
  for (let i = 0; i + 2 < lines.length; i++) {
    if (isDelimiter(lines[i]) && isDelimiter(lines[i + 2])) { starts.push(i); i += 2; }
  }
  return starts.map((start, n) => lines.slice(start, starts[n + 1] ?? lines.length).join('\n').trimEnd());
}

function containsCase(text, block) {
  for (let at = text.indexOf(block); at >= 0; at = text.indexOf(block, at + 1)) {
    const before = at === 0 || text[at - 1] === '\n';
    const after = /^\s*(?:={3,}|$)/.test(text.slice(at + block.length, at + block.length + 200));
    if (before && after) return true;
  }
  return false;
}

// The fork's committed C tests (test/*.c), built from parser sources SRC and the
// runtime sources RUNTIME; a failing test fails the stage.
async function cTests(sh, fork, src, runtime, out, libFlags) {
  fs.mkdirSync(out);
  const cflags = `-std=c11 -D_DEFAULT_SOURCE -O2 -Wall -Wextra -Wno-unused-parameter -Wno-deprecated-declarations ` +
    `-I ${q(src)} -I ${q(`${runtime}/include`)} -I ${q(`${runtime}/src`)}`;
  const objects = [['parser', `${src}/parser.c`, cflags], ['scanner', `${src}/scanner.c`, cflags],
    ['lib', `${runtime}/src/lib.c`, libFlags ?? cflags]];
  await Promise.all(objects.map(([name, source, flags]) => sh(`cc ${flags} -c ${q(source)} -o ${q(`${out}/${name}.o`)}`)));
  const linked = objects.map(([name]) => q(`${out}/${name}.o`)).join(' ');
  const testsC = fs.readdirSync(path.join(fork, 'test')).filter(name => name.endsWith('.c')).sort();
  await Promise.all(testsC.map(name =>
    sh(`cc ${cflags} ${q(path.join(fork, 'test', name))} ${linked} -o ${q(path.join(out, name.slice(0, -2)))}`)));
  const results = [];
  for (const name of testsC) {
    const { stdout } = await sh(q(path.join(out, name.slice(0, -2))), { capture: true });
    results.push(`${name}: ${stdout.trim().split('\n').at(-1)}`);
  }
  return results;
}

async function abi14CTests(run, sh, src) {
  const results = await cTests(sh, run.fork, src, RT22, path.join(run.dir, 'c-tests'),
    // The 0.22.6 runtime defines _POSIX_C_SOURCE itself; with _DEFAULT_SOURCE that is a redefinition.
    `-std=c11 -O2 -Wall -Wextra -Wno-unused-parameter -I ${q(`${RT22}/include`)} -I ${q(`${RT22}/src`)}`);
  run.checkCount('abi14_c_tests', results.length);
  return results;
}

// ts-dump reports ABI14 trees with the unsimplified grammar's node names (see
// grammar-harness/abi14-names.mjs). Both grammar.json files come from the same
// sources as the parser under test.
async function abi14Names(run, sh, output) {
  let unsimplified = path.join(run.dir, 'compat-022/src/grammar.json');
  let simplified = path.join(run.dir, 'compat-abi14/src/grammar.json');
  if (run.tier === 'full') {
    const work = path.join(run.dir, 'names-022');
    fs.mkdirSync(work);
    await sh(`node ${q(`${PARSER}/opengrep/prepare-grammar.cjs`)} ${q(PARSER)} ${q(work)}`);
    await sh(`tree-sitter generate --no-bindings\n${q(GENERATOR)} simplify src/grammar.json src/grammar.simplified.json`,
      { cwd: work });
    unsimplified = path.join(work, 'src/grammar.json');
    simplified = path.join(work, 'src/grammar.simplified.json');
    if (run.selected.includes('compat')) {
      assert.ok(sameFile(simplified, path.join(ROOT, '_build/powershell-grammar/fork/src/grammar.json')),
        'simplified grammar differs from the one opengrep/generate.sh used for opengrep/ocaml');
    }
  }
  return abi14NamesMap(sh, unsimplified, simplified, output);
}

async function runHarness(run, sh, { family, dump, names, base, parser }) {
  const env = `TS_DUMP=${q(dump)} TS_DUMP_PARSER=${q(parser)}${names ? ` TS_DUMP_NAMES=${q(names)}` : ''}`;
  fs.mkdirSync(NATIVE_CACHE, { recursive: true });
  const cacheBefore = fs.readdirSync(NATIVE_CACHE).length;
  const details = {};
  const parts = [];
  let worse = 0;
  for (const batch of run.batches) {
    const out = run.output(family, batch);
    await sh(`${env} node grammar-harness/harness.mjs ${q(path.join(CORPUS, batch))} ${q(out)}`, { cwd: TOOLS });
    const summary = readJson(path.join(out, 'summary.json'));
    const baseDir = base(batch);
    const result = { output: rel(out), categories: summary.categories, elapsed_s: summary.elapsed_s };
    let note = 'no baseline';
    if (baseDir) {
      const compare = await sh(`node grammar-harness/compare-runs.mjs ${q(baseDir)} ${q(out)}`,
        { cwd: TOOLS, capture: true, allowFail: true });
      result.worse = Number(compare.stdout.match(/^worse: (\d+)/m)?.[1]);
      result.moves = JSON.parse(compare.stdout.match(/^moves +(.*)$/m)?.[1] ?? '{}');
      assert.ok(Number.isInteger(result.worse), `${batch}: compare-runs output not recognized`);
      worse += result.worse;
      note = `worse ${result.worse}${Object.keys(result.moves).length ? ` moves ${JSON.stringify(result.moves)}` : ''}`;
    }
    details[batch] = result;
    parts.push(`${batch} ${JSON.stringify(summary.categories)} ${note}`);
  }
  details.native_cache_new_entries = fs.readdirSync(NATIVE_CACHE).length - cacheBefore;
  assert.equal(worse, 0, `grammar results got worse for ${worse} file(s); see compare output in log`);
  details.line = `${parts.join('; ')}; native cache +${details.native_cache_new_entries}`;
  return details;
}

async function grammarStage(run, { sh }) {
  const src = run.tier === 'quick' ? path.join(run.dir, 'compat-abi14/src') : ABI14_LIB;
  const names = path.join(run.dir, 'abi14-names.tsv');
  const mapped = await abi14Names(run, sh, names);
  const dump = path.join(run.dir, 'ts-dump');
  await sh(tsDumpCommand(src, dump));
  const details = await runHarness(run, sh, {
    family: 'grammar', dump, names, base: batch => run.base('grammar', batch),
    parser: `ABI14 parser ${src} on the tree-sitter 0.22.6 runtime; root node names from ${names}`,
  });
  return { parser: 'abi14', parser_sources: src, names: rel(names), names_summary: mapped, ...details, line: `ABI14 ${details.line}` };
}

function countTreeSitterTests(text) {
  // 0.22 prints expected-error cases with a different glyph; colour carries the outcome.
  const results = [...text.matchAll(/^\s+\d+\.\s+(\S*)\s*(?:\x1b\[(\d+)m)?/gm)];
  const passed = results.filter(m => m[1] === '✓' || m[2] === '32').length;
  return { total: results.length, passed, failed: results.length - passed };
}

async function compatFullStage(run, { sh }) {
  const lib = path.join(run.dir, 'compat-lib');
  const { stdout } = await sh(`export TREE_SITTER_LIBDIR=${q(lib)}\nbash ${q(`${PARSER}/opengrep/test.sh`)} ${q(ROOT)}`,
    { capture: true });
  const counts = countTreeSitterTests(stdout);
  assert.ok(counts.passed > 0 && counts.failed === 0, `compatibility tests: ${JSON.stringify(counts)}`);
  run.checkCount('compat_tests', counts.passed);
  const drift = git(PARSER, 'status', '--porcelain', '--', 'opengrep/ocaml');
  const cResults = await abi14CTests(run, sh, ABI14_LIB);
  return {
    compat_tests: counts.passed, generated_drift: drift ? drift.split('\n') : [], c_tests: cResults,
    line: `0.22 tests ${counts.passed}/${counts.total}; regenerated opengrep/ocaml ${drift ? `DIFFERS from HEAD (${drift.split('\n').length} files)` : 'identical to HEAD'}; ` +
      `ABI14 C tests ${cResults.length}/${cResults.length}`,
  };
}

async function compatQuickStage(run, { sh }) {
  const fork = run.fork;
  let counts;
  const { simple } = await buildAbi14(sh, fork, run.dir, {
    async after022(work) {
      fs.mkdirSync(path.join(work, 'test/corpus'), { recursive: true });
      for (const dir of [path.join(fork, 'test/corpus'), path.join(opengrepDir(fork), 'test')]) {
        for (const name of fs.readdirSync(dir).filter(n => n.endsWith('.txt'))) {
          fs.copyFileSync(path.join(dir, name), path.join(work, 'test/corpus', name));
        }
      }
      const { stdout } = await sh(`export TREE_SITTER_LIBDIR=${q(path.join(run.dir, 'compat-lib'))}\ntree-sitter test`,
        { cwd: work, capture: true });
      counts = countTreeSitterTests(stdout);
      assert.ok(counts.passed > 0 && counts.failed === 0, `0.22 tests: ${JSON.stringify(counts)}`);
    },
  });
  const parserC = path.join(simple, 'src/parser.c');
  const matchesCheckedIn = sameFile(parserC, path.join(PARSER, 'opengrep/ocaml/lib/parser.c'));
  const cResults = await abi14CTests(run, sh, path.join(simple, 'src'));
  const probe = path.join(run.dir, 'corpus-probe');
  await sh(`${ABI14_CC} -I ${q(`${simple}/src`)} ${q(`${TOOLS}/corpus/corpus-probe.c`)} ` +
    `${q(parserC)} ${q(`${simple}/src/scanner.c`)} ${ABI14_RUNTIME} -o ${q(probe)}`);

  const details = { compat_tests: counts.passed, abi14_parser_matches_checked_in: matchesCheckedIn, c_tests: cResults };
  const parts = [];
  let regressed = 0;
  for (const batch of run.batches) {
    const base = run.base('corpus', batch);
    if (!base) { parts.push(`${batch} ABI14 no baseline`); continue; }
    const result = await abi14RawParse(run, probe, batch, base);
    details[`abi14_${batch}`] = result;
    regressed += result.regressed.length;
    parts.push(`${batch} ABI14 ${result.files} files: same ${result.same}, improved ${result.improved.length}, ` +
      `changed ${result.changed.length}, regressed ${result.regressed.length}`);
  }
  assert.equal(regressed, 0, `ABI14 raw parse regressed ${regressed} previously clean file(s); see summary.json`);
  details.line = `0.22 tests ${counts.passed}/${counts.total}; ABI14 ${matchesCheckedIn ? '= checked-in ocaml/lib' : 'differs from checked-in ocaml/lib'}; ` +
    `ABI14 C tests ${cResults.length}/${cResults.length}; ${parts.length ? parts.join('; ') : `ABI14 raw parse skipped (${run.noCorpus})`}`;
  return details;
}

async function abi14RawParse(run, probe, batch, base) {
  const batchDir = fs.realpathSync(path.join(CORPUS, batch));
  const unique = [...new Map(readJsonl(path.join(base, 'files.jsonl')).map(row => [row.sha256, row])).values()];
  const inputs = path.join(run.dir, 'inputs');
  const targets = unique.map(row => {
    if (!row.path_bytes_base64) return path.join(batchDir, row.path);
    fs.mkdirSync(inputs, { recursive: true });
    const alias = path.join(inputs, `${row.sha256}${row.extension}`);
    if (!fs.existsSync(alias)) {
      fs.symlinkSync(Buffer.concat([Buffer.from(`${batchDir}/`), Buffer.from(row.path_bytes_base64, 'base64')]), alias);
    }
    return alias;
  });
  const chunk = 200;
  const chunks = [];
  for (let i = 0; i < targets.length; i += chunk) chunks.push(i);
  const raw = [];
  let next = 0;
  await Promise.all(Array.from({ length: 4 }, async () => {
    while (next < chunks.length) {
      const start = chunks[next++];
      const paths = targets.slice(start, start + chunk);
      const child = spawn(probe, paths, { stdio: ['ignore', 'pipe', 'pipe'] });
      let out = '';
      let err = '';
      child.stdout.on('data', data => { out += data; });
      child.stderr.on('data', data => { err += data; });
      const timer = setTimeout(() => child.kill('SIGKILL'), paths.length * 1500 + 10000);
      const [code] = await once(child, 'close');
      clearTimeout(timer);
      assert.equal(code, 0, `ABI14 probe failed: ${err.slice(0, 300)}`);
      const lines = out.trim().split('\n').map(JSON.parse);
      assert.equal(lines.length, paths.length, 'ABI14 probe returned too few results');
      lines.forEach((line, i) => { raw[start + i] = line; });
    }
  }));
  const fields = ['status', 'errors', 'missing'];
  const result = { files: unique.length, same: 0, improved: [], changed: [], regressed: [] };
  unique.forEach((row, i) => {
    const before = row.grammar;
    const after = raw[i];
    const same = fields.every(f => before[f] === after[f]) && JSON.stringify(before.samples) === JSON.stringify(after.samples);
    if (same) result.same++;
    else if (before.status === 'ok') result.regressed.push({ path: row.path, after: after.status, errors: after.errors });
    else if (after.status === 'ok') result.improved.push(row.path);
    else result.changed.push({ path: row.path, before: before.errors, after: after.errors });
  });
  return result;
}

async function buildStage(run, { sh }) {
  await sh(`ocamlformat --check ${OCAML_LINT.map(q).join(' ')}`);
  fs.mkdirSync(path.dirname(PROBE), { recursive: true });
  await sh(`${ABI14_CC} -I ${q(ABI14_LIB)} ${q(`${TOOLS}/corpus/corpus-probe.c`)} ${q(`${ABI14_LIB}/parser.c`)} ` +
    `${q(`${ABI14_LIB}/scanner.c`)} ${ABI14_RUNTIME} -o ${q(PROBE)}`);
  const jobs = Number(run.opts.duneJobs ?? 6);
  await sh(`opam exec -- dune build -j ${jobs} _build/install/default/bin/opengrep src/tests/test.exe`);
  const binary = fs.realpathSync(path.join(ROOT, 'bin/opengrep'));
  return {
    ocamlformat: 'ok', dune_jobs: jobs,
    opengrep_sha256: sha256(binary), corpus_probe_sha256: sha256(PROBE),
    line: `ocamlformat ok; ABI14 corpus probe rebuilt; dune build -j ${jobs} ok`,
  };
}

async function unitStage(run, { sh }) {
  const details = {};
  for (const [key, args] of [['lang_tests', '-t lang.powershell'], ['substring_tests', '-s powershell']]) {
    const { stdout } = await sh(`./test run -j0 ${args}`, { capture: true });
    const m = stdout.match(/(\d+)\/\d+ selected tests:\s+(\d+) successful[^\n]*\n\s+(\d+) unsuccessful/);
    assert.ok(m && m[3] === '0' && m[1] === m[2], `${args}: Testo summary missing or unsuccessful`);
    run.checkCount(key, Number(m[2]));
    details[key] = Number(m[2]);
  }
  details.line = `lang.powershell ${details.lang_tests} passed; substring powershell ${details.substring_tests} passed`;
  return details;
}

function exitStats(dir) {
  const sums = {};
  for (const name of fs.readdirSync(dir).filter(n => n.endsWith('.exit.json'))) {
    const kind = name.includes('.core.') ? 'core' : 'grammar';
    sums[kind] = +((sums[kind] ?? 0) + readJson(path.join(dir, name)).elapsed_ms / 1000).toFixed(3);
  }
  return sums;
}

async function corpusStage(run, { sh }) {
  const details = {};
  const parts = [];
  for (const batch of run.batches) {
    const out = run.output('corpus', batch);
    fs.mkdirSync(out, { recursive: true });
    const start = performance.now();
    await sh(`timeout --signal=TERM --kill-after=5s 10m node ${q(`${TOOLS}/corpus/corpus-baseline.mjs`)} ` +
      `${q(path.join(CORPUS, batch))} ${q(out)} > ${q(`${out}/run.log`)} 2>&1`,
    // Measured 2026-10-22: 8 jobs / 32-file chunks took 19 s versus 47 s for the historical 2 / 16, identical results.
    { env: { CORPUS_JOBS: process.env.CORPUS_JOBS ?? '8', CORPUS_CHUNK_SIZE: process.env.CORPUS_CHUNK_SIZE ?? '32' } });
    const elapsed = +((performance.now() - start) / 1000).toFixed(3);
    const summary = readJson(path.join(out, 'summary.json'));
    const result = { output: rel(out), elapsed_s: elapsed, categories: summary.categories, subprocess_elapsed_sum_s: exitStats(out) };
    let note = 'no baseline';
    const base = run.base('corpus', batch);
    if (base) {
      await sh(`node ${q(`${TOOLS}/corpus/compare-corpus.mjs`)} --allow-grammar-changes ${q(base)} ${q(out)}`, { allowFail: true });
      const comparison = readJson(path.join(out, 'comparison.json'));
      result.regressions = comparison.regressions;
      result.transitions = Object.fromEntries(Object.entries(comparison.transitions).filter(([k]) => {
        const [a, b] = k.split(' -> ');
        return a !== b;
      }));
      result.grammar_transitions = comparison.grammar_transitions;
      assert.equal(comparison.regressions.length, 0, `${batch}: previously successful inputs regressed`);
      note = `regressions 0${Object.keys(result.transitions).length ? ` moves ${JSON.stringify(result.transitions)}` : ''}`;
    }
    details[batch] = result;
    parts.push(`${batch} ${JSON.stringify(summary.categories)} ${note}`);
  }
  details.line = parts.join('; ');
  return details;
}

// Finding and error-file keys of a smoke run (smoke/verify-smoke.mjs writes keys.json):
// a removed finding or a new error file fails; added findings are reported for review.
function compareFindings(baseDir, nowDir) {
  const before = readJson(path.join(baseDir, 'keys.json'));
  const now = readJson(path.join(nowDir, 'keys.json'));
  const nowKeys = new Set(now.findings);
  const beforeKeys = new Set(before.findings);
  const beforeErrors = new Set(before.error_files);
  return {
    removed: before.findings.filter(key => !nowKeys.has(key)),
    added: now.findings.filter(key => !beforeKeys.has(key)),
    new_error_paths: now.error_files.filter(file => !beforeErrors.has(file)),
    errors: now.error_files.length,
  };
}

async function smokeStage(run, { sh }) {
  const details = {};
  const parts = [];
  const failures = [];
  for (const batch of run.batches) {
    const out = run.output('smoke', batch);
    fs.mkdirSync(out, { recursive: true });
    const batchDir = fs.realpathSync(path.join(CORPUS, batch));
    const inventory = path.join(run.output('corpus', batch), 'files.jsonl');
    // Every readable PowerShell file of the batch, by its original name bytes.
    fs.writeFileSync(path.join(out, 'targets.nul'), Buffer.concat(readJsonl(inventory).map(row => Buffer.concat([
      Buffer.from(`${batchDir}/`), row.path_bytes_base64 ? Buffer.from(row.path_bytes_base64, 'base64') : Buffer.from(row.path),
      Buffer.from([0])]))));
    await sh(`set +e\ntimeout --signal=TERM --kill-after=5s 10m xargs -0 -s 1800000 ./bin/opengrep scan --config ${q(SMOKE_RULES)} ` +
      `--json --no-git-ignore --max-target-bytes 0 --no-exclude-minified-files --no-strict ` +
      `< ${q(`${out}/targets.nul`)} > ${q(`${out}/results.json`)} 2> ${q(`${out}/scan.stderr`)}\ncode=$?\nset -e\n` +
      `printf '%s\\n' "$code" > ${q(`${out}/exit-code.txt`)}\ntest "$code" -eq 0`);
    await sh(`node smoke/verify-smoke.mjs ${q(out)} ${q(batchDir)} ${q(inventory)} ${q(SMOKE_RULES)} > ${q(`${out}/verification.stdout`)}`,
      { cwd: TOOLS });
    const summary = readJson(path.join(out, 'summary.json'));
    const result = { output: rel(out), targets: summary.targets, findings: summary.findings, findings_by_rule: summary.findings_by_rule,
      files: summary.matching_files, captures: summary.validated_capture_byte_ranges, errors: summary.error_files.length };
    const base = run.base('smoke', batch);
    let note = 'no baseline';
    if (base) {
      const comparison = compareFindings(base, out);
      fs.writeFileSync(path.join(out, 'finding-set-comparison.json'), `${JSON.stringify(comparison, null, 2)}\n`);
      Object.assign(result, { removed: comparison.removed.length, added: comparison.added.length, new_error_paths: comparison.new_error_paths });
      if (comparison.removed.length) failures.push(`${batch}: ${comparison.removed.length} finding(s) removed`);
      if (comparison.new_error_paths.length) failures.push(`${batch}: new scan errors in ${comparison.new_error_paths.length} file(s)`);
      note = `removed ${comparison.removed.length}, added ${comparison.added.length}, new error files ${comparison.new_error_paths.length}`;
    }
    details[batch] = result;
    parts.push(`${batch} ${result.targets} targets, ${result.findings} findings / ${result.captures} captures byte-checked, ` +
      `${result.errors} scan error files; ${note}`);
  }
  assert.deepEqual(failures, [], failures.join('; '));
  details.line = parts.join('; ');
  return details;
}

// ---------------------------------------------------------------- driver

function relock(argv) {
  fs.mkdirSync(path.dirname(LOCK), { recursive: true });
  if (spawnSync('flock', ['-n', LOCK, 'true']).status !== 0) console.log('Waiting for another full validation to finish...');
  const result = spawnSync('flock', ['-x', LOCK, process.execPath, SELF, ...argv],
    { stdio: 'inherit', env: { ...process.env, VALIDATE_LOCK_HELD: '1' } });
  process.exit(result.status ?? 1);
}

function writeSummary(run, started) {
  const failed = run.stages.find(stage => stage.status === 'fail');
  const result = failed ? 'fail' : 'pass';
  const total = (performance.now() - started) / 1000;
  const summary = {
    tier: run.tier, label: run.label, baseline: run.baseline ?? null,
    corpus: { root: CORPUS, batches: run.batches, notice: run.noCorpus ?? null },
    result, complete: run.complete && !failed, certification: run.tier === 'full' && run.complete && !failed,
    started_at: run.startedAt, completed_at: new Date().toISOString(), wall_s: +total.toFixed(3),
    host: { cpus: os.cpus().length, loadavg_at_start: run.loadavgAtStart },
    identity: run.identity, counts: run.counts, stages: run.stages,
    skipped: STAGES[run.tier].filter(name => !run.selected.includes(name)),
  };
  fs.writeFileSync(path.join(run.dir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
  const tree = identity => `${identity.short}${identity.dirty ? ' (dirty)' : ''}`;
  const lines = [
    `validate ${run.tier} ${run.label}: ${result.toUpperCase()}${summary.certification ? ' (certification)' : run.complete ? '' : ' (partial)'} ` +
      `in ${duration(total)}; baseline ${run.baseline?.label ?? 'none'}`,
    run.tier === 'full'
      ? `opengrep ${tree(run.identity.opengrep)} parser ${tree(run.identity.parser)} pin ${run.identity.pin_matches ? 'matches' : 'DIFFERS'}`
      : `fork ${run.identity.fork.path} ${tree(run.identity.fork)} [${run.identity.fork.branch}]`,
    ...run.stages.map(stage => `${stage.status.toUpperCase().padEnd(4)} ${stage.name.padEnd(8)} ` +
      `${duration(stage.wall_s).padStart(6)} wall ${duration(stage.child_cpu_s).padStart(6)} cpu  ` +
      `${stage.status === 'pass' ? stage.details.line : stage.error}`),
    ...summary.skipped.map(name => `SKIP ${name}${run.noCorpus && CORPUS_STAGES.includes(name) ? ` (${run.noCorpus})` : ''}`),
  ];
  if (run.noCorpus) lines.push(`NOTICE ${run.noCorpus}: corpus layers skipped; this run is not a certification`);
  if (failed) lines.push(`log: ${failed.log}`);
  lines.push(`summary: ${rel(path.join(run.dir, 'summary.json'))}`);
  fs.writeFileSync(path.join(run.dir, 'summary.txt'), `${lines.join('\n')}\n`);
  console.log(`\n${lines.join('\n')}`);
  if (failed) {
    const tail = fs.readFileSync(path.join(AI_DOCS, failed.log), 'utf8').trimEnd().split('\n').slice(-25).join('\n');
    console.log(`\n--- last lines of ${failed.log} ---\n${tail}`);
  }
  return result === 'pass' ? 0 : 1;
}

function promote(opts) {
  const label = opts.positional[0];
  assert.ok(label, 'usage: node ai-docs/tools/validate.mjs promote LABEL [--allow-dirty]');
  const summary = readJson(path.join(RUNS, label, 'summary.json'));
  assert.ok(summary.certification, `${label} is not a complete passing full validation`);
  const dirty = summary.identity.opengrep.dirty || summary.identity.parser.dirty;
  assert.ok(!dirty || opts.allowDirty, `${label} validated an uncommitted tree; commit and re-run, or pass --allow-dirty`);
  const baselines = loadBaselines();
  if (baselines.current) baselines.history.push({ ...baselines.current, replaced_at: new Date().toISOString() });
  // Result folders are local/runs/LABEL/{grammar,corpus,smoke}/BATCH.
  baselines.current = {
    label, description: `Opengrep ${summary.identity.opengrep.short} / parser ${summary.identity.parser.short}` +
      `${dirty ? ' (validated before commit)' : ''}, validate run ${label}`,
    batches: summary.corpus.batches,
    // Floors of stages this run did not measure carry over.
    counts: { ...baselines.current?.counts, ...summary.counts },
  };
  fs.writeFileSync(BASELINES, `${JSON.stringify(baselines, null, 2)}\n`);
  console.log(`current baseline is now ${label}`);
}

async function main() {
  const argv = process.argv.slice(2);
  const opts = parseArgs(argv);
  if (opts.tier === 'promote') return promote(opts);
  assert.ok(STAGES[opts.tier], 'usage: node ai-docs/tools/validate.mjs quick|full|promote ... (see header of validate.mjs)');
  if (opts.tier === 'full' && !process.env.VALIDATE_LOCK_HELD) relock(argv);
  const run = new Run(opts);
  const started = performance.now();
  run.startedAt = new Date().toISOString();
  run.loadavgAtStart = os.loadavg();
  run.identity = run.tier === 'full'
    ? {
      opengrep: gitIdentity(ROOT), parser: gitIdentity(PARSER),
      pin: git(ROOT, 'ls-tree', 'HEAD', path.relative(ROOT, PARSER)).split(/\s+/)[2],
    }
    : { fork: gitIdentity(run.fork) };
  if (run.identity.pin) run.identity.pin_matches = run.identity.pin === run.identity.parser.head;
  console.log(`validate ${run.tier} ${run.label}: stages ${run.selected.join(', ')}; logs in ${rel(run.dir)}/logs`);
  if (run.noCorpus) console.log(`NOTICE ${run.noCorpus}: skipping ${CORPUS_STAGES.join(', ')}; this run is not a certification`);
  const impl = {
    source: sourceStage, compat: run.tier === 'full' ? compatFullStage : compatQuickStage, grammar: grammarStage,
    build: buildStage, unit: unitStage, corpus: corpusStage, smoke: smokeStage,
  };
  for (const name of run.selected) {
    if (!await run.stage(name, ctx => impl[name](run, ctx))) break;
  }
  if (run.tier === 'quick') {
    const after = gitIdentity(run.fork);
    if (JSON.stringify(after.status) !== JSON.stringify(run.identity.fork.status)) {
      run.stages.push({ name: 'worktree', status: 'fail', wall_s: 0, child_cpu_s: 0, log: rel(path.join(run.dir, 'logs')),
        error: `validation changed the fork worktree: ${after.status.join(', ')}` });
    }
  }
  process.exitCode = writeSummary(run, started);
  // Rebuildable intermediates (~65 MB per run); kept after a failure for debugging.
  if (process.exitCode === 0 && !opts.keepScratch) {
    for (const name of SCRATCH) fs.rmSync(path.join(run.dir, name), { recursive: true, force: true });
  }
}

await main();
